/**
 * catalog.js — 部件库数据层
 * 从 docs/parts-classification.json 派生前端展示结构。
 * 单位换算：原始单位 1 = 10cm，展示用米（×0.1，保留 3 位）。
 *
 * 编号规则：
 * - 墙体：墙体01~墙体10（Z负端墙 3 → Z正端墙 2 → X负端墙 2 → X正端墙 3，
 *   面内按主轴坐标升序；Mesh59 归入框架竖向立柱，Mesh118 归入 X 正端墙）
 * - 框架：竖向立柱01~09 / 底部短柱01~06 / 顶部短柱01~10 / 底部横梁01~06 /
 *   顶部横梁01~06 / 底座垫块01~04 / 柱身饰件01~04（组内按 z→x→y 坐标升序）
 */
import raw from '../data/parts-classification.json'

/** 模型整体缩放系数（GLB 原始单位 → 场景米；用户要求缩放到原一半） */
export const SCALE = 0.03
/** GLB 原始尺寸（1 单位 = 10cm） */
export const MODEL_ORIG = { x: 48.565, y: 24.8, z: 59.0 }

const M = SCALE
const toM = (v) => Math.round(v * M * 1000) / 1000
const fmtSize = (s) => s.map(toM)
const fmtPos = (c) => c.map(toM)
const pad = (n) => String(n).padStart(2, '0')

export const MODEL_INFO = {
  file: raw.model,
  totalParts: raw.totalParts,
  unit: '原始单位（1 = 10cm，展示为米）'
}

const groups = {}
raw.groups.forEach((g) => { groups[g.id] = g })

/** 部件条目 */
function partEntry(p, sub, opts = {}) {
  return {
    id: opts.id || p.name,     // 选中键（墙体/框架编号部件用编号 id）
    name: opts.name || p.name, // 显示名（墙体01 / 竖向立柱01 / MeshN）
    mesh: p.name,              // GLB 内原始 mesh 名
    sub: sub || '',
    material: p.material,
    size: fmtSize(p.size),     // 米
    sizeRaw: p.size,           // 原始单位
    center: fmtPos(p.center)   // 米
  }
}

/** 按坐标排序：axisSeq 为比较轴顺序（原始单位中心坐标，先比较的轴优先） */
function sortByAxes(parts, axisSeq) {
  return [...parts].sort((a, b) => {
    for (const ax of axisSeq) {
      if (a.center[ax] !== b.center[ax]) return a.center[ax] - b.center[ax]
    }
    return 0
  })
}

/** 组合体条目（窗 / 门 / 屋顶 / 地板） */
function comboItem(item, group) {
  return {
    id: item.id,
    name: item.name,
    group: group.name,
    type: group.type,
    kind: 'combo',
    role: item.role || '',
    wall: item.wall || '',
    parts: item.parts.map((p) => partEntry(p)),
    box: item.box
      ? { min: item.box.min.map(toM), max: item.box.max.map(toM), size: item.box.size.map(toM) }
      : null,
    count: item.parts.length
  }
}

/** 墙体：4 面墙 → 墙体01~10（面内从左到右编号） */
function buildWallGroups() {
  let seq = 0
  return groups.wall.items.map((it) => {
    // Z 向墙（法向 ±Z）面内主轴为 x；X 向墙（法向 ±X）面内主轴为 z
    const axis = it.id.indexOf('_xn') >= 0 || it.id.indexOf('_xp') >= 0 ? 2 : 0
    const sorted = sortByAxes(it.parts, [axis])
    const parts = sorted.map((p) => {
      seq++
      return partEntry(p, it.name, { id: `wall_${pad(seq)}`, name: `墙体${pad(seq)}` })
    })
    return {
      id: it.id, name: it.name, group: '墙体', type: it.type,
      kind: 'part-group', parts, count: parts.length
    }
  })
}

/** 框架：7 类 → 竖向立柱01~08 等（组内按 z→x→y 排序编号） */
function buildFrameGroups() {
  return groups.frame.items.map((it) => {
    const sorted = sortByAxes(it.parts, [2, 0, 1])
    const parts = sorted.map((p, i) => {
      const n = i + 1
      return partEntry(p, it.name, { id: `${it.id}_${pad(n)}`, name: `${it.name}${pad(n)}` })
    })
    return {
      id: it.id, name: it.name, group: '框架', type: it.type,
      kind: 'part-group', parts, count: parts.length
    }
  })
}

export function buildCatalog() {
  const doorGroup = groups.door
  const floorGroup = groups.floor
  const roofGroup = groups.roof

  // 门 = 1 个大部件（两扇 14 个部件合并，保留子组信息）
  const doorSubs = doorGroup.items.map((it) => ({
    id: it.id,
    name: it.name,
    parts: it.parts.map((p) => partEntry(p, it.name)),
    count: it.parts.length
  }))
  const door = {
    id: 'door',
    name: '门',
    group: '门',
    type: 'door',
    kind: 'combo',
    role: '整门（两扇）',
    subs: doorSubs,
    parts: doorGroup.items.flatMap((it) => it.parts.map((p) => partEntry(p, it.name))),
    count: doorGroup.items.reduce((n, it) => n + it.parts.length, 0),
    box: null
  }

  const roof = {
    id: 'roof',
    name: '屋顶',
    group: '屋顶',
    type: 'roof',
    kind: 'combo',
    role: '屋顶组件',
    parts: roofGroup.parts.map((p) => partEntry(p)),
    count: roofGroup.parts.length,
    box: roofGroup.box ? { min: roofGroup.box.min.map(toM), max: roofGroup.box.max.map(toM), size: roofGroup.box.size.map(toM) } : null
  }

  const floor = {
    id: 'floor',
    name: '地板',
    group: '地板',
    type: 'floor',
    kind: 'combo',
    role: '地板组件',
    parts: floorGroup.parts.map((p) => partEntry(p)),
    count: floorGroup.parts.length,
    box: floorGroup.box ? { min: floorGroup.box.min.map(toM), max: floorGroup.box.max.map(toM), size: floorGroup.box.size.map(toM) } : null
  }

  const sections = [
    {
      id: 'window', name: '窗户', unit: '扇', color: '#38bdf8',
      type: 'combo-list', count: groups.window.items.length,
      items: groups.window.items.map((it) => comboItem(it, groups.window))
    },
    {
      id: 'door', name: '门', unit: '扇', color: '#f59e0b',
      type: 'combo-list', count: 1,
      items: [door]
    },
    {
      id: 'roof', name: '屋顶', unit: '个', color: '#ef4444',
      type: 'combo-list', count: 1,
      items: [roof]
    },
    {
      id: 'floor', name: '地板', unit: '个', color: '#8b98a5',
      type: 'combo-list', count: 1,
      items: [floor]
    },
    {
      id: 'wall', name: '墙体', unit: '个', color: '#64748b',
      type: 'flat-groups', count: groups.wall.items.reduce((n, it) => n + it.parts.length, 0),
      groups: buildWallGroups()
    },
    {
      id: 'frame', name: '框架', unit: '个', color: '#334155',
      type: 'flat-groups', count: groups.frame.items.reduce((n, it) => n + it.parts.length, 0),
      groups: buildFrameGroups()
    }
  ]

  return { sections, door, roof, floor }
}

export const catalog = buildCatalog()
